<template><CoopTaskSheet :show="show" title="选择意向型号" subtitle="直接搜索，可多选；不需要填写设备台数" full @close="$emit('close')"><view class="coop-model-picker"><u-search v-model="keyword" placeholder="搜索客户需要的型号" :show-action="true" action-text="搜索" @search="load" @custom="load" @clear="load" /><view v-if="chosen.length" class="coop-picker-selected"><view class="coop-minor">已选型号</view><view class="coop-selected-chips"><text v-for="item in chosen" :key="String(item.id)" @tap="toggle(item)">{{ item.title }} ×</text></view></view><CoopState v-if="loading || error" :loading="loading" :error="error" @retry="load" /><template v-else><view class="coop-picker-result-title">搜索结果<text>可多选</text></view><view v-for="item in rows" :key="String(item.id)" class="coop-picker-result" @tap="toggle(item)"><view class="coop-device-thumb"><u-icon name="phone" size="24" color="#8897a8" /></view><view class="coop-picker-model"><view>{{ item.title }}</view><text>{{ item.brand }}</text></view><u-icon :name="isSelected(item) ? 'checkmark-circle-fill' : 'circle'" size="22" :color="isSelected(item) ? 'var(--primary-color, #d93833)' : '#d0d6df'" /></view><CoopState v-if="!rows.length" title="没找到匹配型号" hint="试试完整型号名称，或联系平台补充型号资料" icon="search" /></template></view><template #footer><u-button type="primary" shape="circle" text="完成选择" @click="confirm" /></template></CoopTaskSheet></template>
<script setup lang="ts">
import { onBeforeUnmount, ref, watch } from 'vue'
import { cooperationCatalog, coopError, type CoopRow } from '../../api/cooperation'
import CoopTaskSheet from './CoopTaskSheet.vue'
import CoopState from './CoopState.vue'
const props = defineProps<{ show: boolean; modelValue: CoopRow[] }>()
const emit = defineEmits<{ (event: 'close'): void; (event: 'update:modelValue', value: CoopRow[]): void }>()
const keyword = ref(''), rows = ref<CoopRow[]>([]), chosen = ref<CoopRow[]>([]), loading = ref(false), error = ref('')
let sequence = 0, timer: ReturnType<typeof setTimeout> | undefined
function isSelected(row: CoopRow) { return chosen.value.some(item => String(item.id) === String(row.id)) }
function toggle(row: CoopRow) { if (!isSelected(row) && chosen.value.length >= 20) { uni.showToast({ title: '最多选择20个意向型号', icon: 'none' }); return }; chosen.value = isSelected(row) ? chosen.value.filter(item => String(item.id) !== String(row.id)) : [...chosen.value, { id: String(row.id), title: row.title, brand: row.brand }] }
async function load() { if (timer) { clearTimeout(timer); timer = undefined }; if (!props.show) return; const token = ++sequence; loading.value = true; error.value = ''; try { const response: any = await cooperationCatalog(keyword.value.trim()); if (token === sequence && props.show) rows.value = Array.isArray(response.data) ? response.data : response.data?.data || [] } catch (cause) { if (token === sequence && props.show) error.value = coopError(cause, '型号读取失败') } finally { if (token === sequence) loading.value = false } }
function confirm() { emit('update:modelValue', chosen.value); emit('close') }
watch(() => props.show, show => { if (show) { chosen.value = props.modelValue.map(item => ({ ...item, id: String(item.id) })); keyword.value = ''; void load() } else { sequence++; loading.value = false; if (timer) clearTimeout(timer) } })
watch(keyword, () => { if (timer) clearTimeout(timer); timer = setTimeout(load, 300) }, { flush: 'sync' })
onBeforeUnmount(() => { sequence++; if (timer) clearTimeout(timer) })
</script>
<style scoped lang="scss">.coop-model-picker { padding: 26rpx 30rpx; background: #fff; min-height: 100%; }.coop-picker-selected { padding: 30rpx 0 34rpx; border-bottom: 1rpx solid #edf0f3; }.coop-minor { font-size: 23rpx; color: #88919c; margin-bottom: 17rpx; }.coop-selected-chips { display: flex; flex-wrap: wrap; gap: 12rpx; }.coop-selected-chips>text { font-size: 23rpx; padding: 12rpx 15rpx; border: 1rpx solid #e1e6ec; background: #f5f6f8; border-radius: 7rpx; color: #626d7b; line-height: 1.6; }.coop-picker-result-title { display: flex; justify-content: space-between; margin: 32rpx 0 10rpx; font-size: 28rpx; font-weight: 600; }.coop-picker-result-title>text { font-size: 23rpx; color: #949ba6; font-weight: 400; }.coop-picker-result { display: flex; gap: 20rpx; align-items: center; min-height: 152rpx; border-bottom: 1rpx solid #edf0f3; }.coop-device-thumb { width: 76rpx; height: 94rpx; background: #f3f5f7; border-radius: 8rpx; display: flex; align-items: center; justify-content: center; flex: none; }.coop-picker-model { min-width: 0; flex: 1; font-size: 28rpx; color: #363f4b; font-weight: 600; line-height: 1.6; word-break: break-word; }.coop-picker-model>text { color: #949ca7; font-size: 23rpx; font-weight: 400; }</style>
